// src/pages/Dashboard.jsx
import { useState, useEffect } from "react";
import C from "../constants/colors";
import { MARKET_DATA } from "../constants/data";
import Card from "../components/ui/Card";
import TrendPill from "../components/ui/TrendPill";

function Dashboard({ user, setPage, t }) {
  const [weather, setWeather] = useState({
    temp: 32,
    humidity: 72,
    description: "Partly cloudy",
    icon: "⛅",
    city: user.district || "Madurai",
    windSpeed: 3.2,
    rain: 0,
  });

  useEffect(() => {
    navigator.geolocation?.getCurrentPosition(
      async (pos) => {
        const { latitude: lat, longitude: lon } = pos.coords;
        try {
          const [weatherRes, geoRes] = await Promise.all([
            fetch(
              `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}` +
              `&current=temperature_2m,relative_humidity_2m,weather_code,wind_speed_10m,precipitation`
            ),
            fetch(`https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lon}&format=json`),
          ]);
          const w = await weatherRes.json();
          const g = await geoRes.json();
          const cur = w.current;

          const getWeatherMeta = (code, temp) => {
            if (code === 0)  return { desc: "Clear sky",    icon: temp >= 30 ? "☀️" : "🌙" };
            if (code <= 2)   return { desc: "Mostly clear", icon: "🌤️" };
            if (code === 3)  return { desc: "Overcast",     icon: "☁️" };
            if (code <= 49)  return { desc: "Foggy",        icon: "🌫️" };
            if (code <= 55)  return { desc: "Drizzle",      icon: "🌦️" };
            if (code <= 67)  return { desc: "Rainy",        icon: "🌧️" };
            if (code <= 77)  return { desc: "Snowy",        icon: "❄️" };
            if (code <= 82)  return { desc: "Showers",      icon: "🌨️" };
            if (code <= 99)  return { desc: "Thunderstorm", icon: "⛈️" };
            return                   { desc: "Unknown",     icon: "🌡️" };
          };

          const { desc, icon } = getWeatherMeta(cur.weather_code, cur.temperature_2m);
          setWeather({
            temp:        Math.round(cur.temperature_2m),
            humidity:    cur.relative_humidity_2m,
            description: desc,
            icon,
            city:        g.address?.city || g.address?.town || g.address?.village || user.district,
            windSpeed:   cur.wind_speed_10m,
            rain:        cur.precipitation ?? 0,
          });
        } catch (err) {
          console.warn("Weather fetch failed:", err);
        }
      },
      () => console.warn("Geolocation denied — using defaults")
    );
  }, []);

  // ── Translated alert messages ─────────────────────────────────────────────
  const alerts = [
    { type: "danger",  msg: t("dashboard.alerts")?.[0] || "Pest: Fall Armyworm spotted in Dindigul — check maize immediately", time: "2h" },
    { type: "warning", msg: t("dashboard.alerts")?.[1] || "High humidity next 48hrs — blight risk HIGH for tomato & chilli",   time: "5h" },
    { type: "success", msg: t("dashboard.alerts")?.[2] || "PM-KISAN 19th installment released — check your bank account",      time: "1d" },
  ];

  const bars = [
    { label: t("dashboard.weatherRisk")     || "Weather Risk",       val: 65, c: C.orange },
    { label: t("dashboard.diseasePressure") || "Disease Pressure",   val: 78, c: C.red    },
    { label: t("dashboard.soilHealth")      || "Soil Health",        val: 82, c: C.bg2    },
    { label: t("dashboard.pestAlert")       || "Pest Alert",         val: 55, c: C.amber  },
  ];

  const quickActions = [
    {
      icon: "🤖",
      label: t("nav.bot")     || "AI Agro Bot",
      sub:   t("bot.subtitle")?.slice(0, 30) || "Ask anything",
      page:  "bot",
      bg:    `linear-gradient(135deg,${C.bg1},${C.dark})`,
    },
    {
      icon: "🔬",
      label: t("nav.disease") || "Disease Detect",
      sub:   t("disease.subtitle")?.slice(0, 30) || "Upload photo",
      page:  "disease",
      bg:    "linear-gradient(135deg,#1a5090,#0d2d5e)",
    },
    {
      icon: "🗺️",
      label: t("nav.map")    || "Farm Map",
      sub:   t("map.subtitle")?.slice(0, 30) || "View land",
      page:  "map",
      bg:    "linear-gradient(135deg,#1a5a40,#0a2e1e)",
    },
    {
      icon: "📈",
      label: t("nav.market") || "Market Prices",
      sub:   t("market.subtitle")?.slice(0, 30) || "Live rates",
      page:  "market",
      bg:    "linear-gradient(135deg,#8a4a10,#4a2408)",
    },
  ];

  return (
    <div style={{ padding: 22 }}>

      {/* ── Greeting ─────────────────────────────────────────────────────── */}
      <h1 style={{ fontSize: 22, fontWeight: 700, color: C.text, margin: "0 0 4px" }}>
        👋 {t("dashboard.greeting") || "Good morning"}, {user.name}!
      </h1>

      {/* ── Location + Weather ────────────────────────────────────────────── */}
      <div style={{ marginBottom: 18, display: "flex", justifyContent: "space-between", alignItems: "flex-end" }}>
        <p style={{ color: C.muted, fontSize: 13, margin: 0 }}>
          {user.district}, {t("dashboard.district") || "Tamil Nadu"} • {new Date().toLocaleDateString("en-IN", { day: "numeric", month: "long", year: "numeric" })}
        </p>
        <div style={{ textAlign: "right" }}>
          <div style={{ fontSize: 22, fontWeight: 700, color: C.text }}>
            {weather.temp}°C {weather.icon}
          </div>
          <div style={{ fontSize: 12, color: C.muted }}>
            {weather.humidity}% {t("dashboard.weatherLabel") || "humidity"} • {weather.description}
          </div>
        </div>
      </div>

      {/* ── Stat Cards ───────────────────────────────────────────────────── */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 10, marginBottom: 14 }}>
        {[
          { l: t("dashboard.confluenceScore") || "Confluence Score", v: "72%",                    s: t("dashboard.mediumRisk")      || "Medium Risk",     c: C.orange },
          { l: t("dashboard.activeAlerts")    || "Active Alerts",    v: "3",                      s: t("dashboard.highPriority")    || "2 High Priority", c: C.red    },
          { l: t("dashboard.cropsTracked")    || "Crops Tracked",    v: user.crops?.length || 0,  s: t("dashboard.registeredCrops") || "Registered",      c: C.bg2    },
          { l: t("dashboard.farmPlots")       || "Farm Plots",       v: user.farms?.length || 0,  s: t("dashboard.mappedGPS")       || "Mapped on GPS",   c: C.blue   },
        ].map(s => (
          <Card key={s.l} style={{ padding: "12px 14px" }}>
            <div style={{ fontSize: 10.5, color: C.muted, textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: 3 }}>{s.l}</div>
            <div style={{ fontSize: 26, fontWeight: 700, color: s.c }}>{s.v}</div>
            <div style={{ fontSize: 11, color: C.muted, marginTop: 1 }}>{s.s}</div>
          </Card>
        ))}
      </div>

      {/* ── Alerts + Risk Analysis ────────────────────────────────────────── */}
      <div style={{ display: "grid", gridTemplateColumns: "1.1fr 0.9fr", gap: 14, marginBottom: 14 }}>

        {/* Alerts */}
        <Card>
          <div style={{ fontSize: 13, fontWeight: 600, color: C.text, marginBottom: 10 }}>
            ⚠️ {t("dashboard.activeFarmAlerts") || "Active Alerts"}
          </div>
          {alerts.map((a, i) => (
            <div key={i} style={{ display: "flex", gap: 9, padding: "8px 0", borderBottom: i < 2 ? `1px solid ${C.border}` : "none" }}>
              <div style={{
                width: 8, height: 8, borderRadius: "50%", marginTop: 5, flexShrink: 0,
                background: a.type === "danger" ? C.red : a.type === "warning" ? C.orange : C.bg2,
              }} />
              <div>
                <div style={{ fontSize: 12.5, color: C.text, lineHeight: 1.4 }}>{a.msg}</div>
                <div style={{ fontSize: 11, color: C.muted, marginTop: 2 }}>{a.time} {t("common.just_now") ? "" : "ago"}</div>
              </div>
            </div>
          ))}
        </Card>

        {/* Risk bars */}
        <Card>
          <div style={{ fontSize: 13, fontWeight: 600, color: C.text, marginBottom: 10 }}>
            🎯 {t("dashboard.riskAnalysis") || "Risk Analysis"}
          </div>
          {bars.map(b => (
            <div key={b.label} style={{ marginBottom: 10 }}>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12, marginBottom: 3 }}>
                <span style={{ color: C.text }}>{b.label}</span>
                <span style={{ color: b.c, fontWeight: 600 }}>{b.val}%</span>
              </div>
              <div style={{ height: 5, background: "#e0ead4", borderRadius: 3, overflow: "hidden" }}>
                <div style={{ height: "100%", width: `${b.val}%`, background: b.c, borderRadius: 3 }} />
              </div>
            </div>
          ))}
        </Card>
      </div>

      {/* ── Market Movers ─────────────────────────────────────────────────── */}
      <Card style={{ marginBottom: 14 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
          <div style={{ fontSize: 13, fontWeight: 600, color: C.text }}>
            📊 {t("dashboard.todayMarket") || "Today's Market Highlights"}
          </div>
          <button onClick={() => setPage("market")}
            style={{ fontSize: 12, color: C.bg2, background: "none", border: "none", cursor: "pointer" }}>
            {t("viewAll") || "View All"} →
          </button>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(6,1fr)", gap: 8 }}>
          {MARKET_DATA.filter(p => p.trend !== "flat").slice(0, 6).map(p => (
            <div key={p.crop} style={{ textAlign: "center", padding: "10px 6px", background: C.bg, borderRadius: 8 }}>
              <div style={{ fontSize: 10.5, color: C.muted, marginBottom: 2 }}>{p.crop}</div>
              <div style={{ fontSize: 13.5, fontWeight: 700, color: C.text }}>₹{p.modal.toLocaleString()}</div>
              <TrendPill trend={p.trend} change={p.change} />
            </div>
          ))}
        </div>
      </Card>

      {/* ── Quick Actions ─────────────────────────────────────────────────── */}
      <div style={{ fontSize: 13, fontWeight: 600, color: C.text, marginBottom: 10 }}>
        ⚡ {t("dashboard.quickActions") || "Quick Actions"}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 10 }}>
        {quickActions.map(c => (
          <div key={c.page} onClick={() => setPage(c.page)}
            style={{ background: c.bg, borderRadius: 12, padding: "16px 14px", cursor: "pointer" }}>
            <div style={{ fontSize: 28, marginBottom: 6 }}>{c.icon}</div>
            <div style={{ fontSize: 14, fontWeight: 600, color: "#fff" }}>{c.label}</div>
            <div style={{ fontSize: 11.5, color: "rgba(255,255,255,0.65)", marginTop: 2 }}>{c.sub} →</div>
          </div>
        ))}
      </div>

      {/* ── Your Crops ───────────────────────────────────────────────────── */}
      {user.crops?.length > 0 && (
        <Card style={{ marginTop: 14 }}>
          <div style={{ fontSize: 13, fontWeight: 600, color: C.text, marginBottom: 10 }}>
            🌾 {t("dashboard.yourCrops") || "Your Crops"}
          </div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 7 }}>
            {user.crops.map(c => (
              <span key={c} style={{ padding: "5px 12px", background: C.pale, borderRadius: 16, fontSize: 12.5, color: C.bg2, border: `1px solid ${C.border}` }}>
                {c}
              </span>
            ))}
          </div>
        </Card>
      )}
    </div>
  );
}

export default Dashboard;
